  "INSERT INTO entries (collection, slug, position, status, data, author, last_editor)\nSELECT 'faqs', 'can-this-be-scoped-smaller', 0, 'published', '{\"question\": \"Can this be scoped smaller?\", \"answer\": \"Yes. The scope is whatever the problem turns out to need, and a single system can be fixed on its own.\\n\\nWhat there is no smaller version of is the build itself. Nothing here sits on a template.\"}', 'import', 'import'\nWHERE NOT EXISTS (SELECT 1 FROM entries WHERE collection = 'faqs' AND slug = 'can-this-be-scoped-smaller');",
  "INSERT INTO entries (collection, slug, position, status, data, author, last_editor)\nSELECT 'faqs', 'what-is-included', 1, 'published', '{\"question\": \"What is included?\", \"answer\": \"Design, build, launch, search setup, an analytics dashboard, documentation, and support after hand over.\\n\\nYou get the analytics to show the work actually did something.\"}', 'import', 'import'\nWHERE NOT EXISTS (SELECT 1 FROM entries WHERE collection = 'faqs' AND slug = 'what-is-included');",
  "INSERT INTO entries (collection, slug, position, status, data, author, last_editor)\nSELECT 'faqs', 'do-you-build-mobile-applications', 2, 'published', '{\"question\": \"Do you build mobile applications?\", \"answer\": \"Yes. Websites, customer-facing apps, staff tools, and internal systems that replace the spreadsheets a business has outgrown.\"}', 'import', 'import'\nWHERE NOT EXISTS (SELECT 1 FROM entries WHERE collection = 'faqs' AND slug = 'do-you-build-mobile-applications');",
  "INSERT INTO entries (collection, slug, position, status, data, author, last_editor)\nSELECT 'faqs', 'how-long-does-a-project-take', 3, 'published', '{\"question\": \"How long does a project take?\", \"answer\": \"It depends on scope. Most projects run several weeks end to end.\\n\\nWhatever the answer is, you get the date in writing before any work begins, along with the scope and the figure.\"}', 'import', 'import'\nWHERE NOT EXISTS (SELECT 1 FROM entries WHERE collection = 'faqs' AND slug = 'how-long-does-a-project-take');",
  "INSERT INTO entries (collection, slug, position, status, data, author, last_editor)\nSELECT 'faqs', 'who-actually-works-on-the-project', 4, 'published', '{\"question\": \"Who actually works on the project?\", \"answer\": \"Me. The person you speak to on the first call is the person who builds it, and the person who answers when something breaks.\\n\\nNo account managers and no handoffs to a queue.\"}', 'import', 'import'\nWHERE NOT EXISTS (SELECT 1 FROM entries WHERE collection = 'faqs' AND slug = 'who-actually-works-on-the-project');",
